import React, { useState, useEffect, useRef, useId } from 'react';
import { createRoot } from 'react-dom/client';
import { ArrowRight, ArrowLeft, ArrowUpRight, Plus, X, Check, CheckCheck, ChevronRight, ChevronDown, ChevronUp, CalendarDays, Clock3, MapPin, Users, MessageCircle, Bell, Search, SlidersHorizontal, Leaf, Sprout, Sun, Sparkles, Gamepad2, Utensils, Dices, ShoppingBag, Trees, Home, UserRound, Send, Pencil, Trash2, Share2, Wallet, Route, CircleCheck, CircleHelp, AlertCircle, Info, LoaderCircle, Navigation, Flag, MoreHorizontal, Heart, Coffee, Copy, Cloud, Fish, Star, Flower2, ShieldCheck, LogOut } from 'lucide-react';
import { MEMBERS, member, TYPES, STATUS, RSVP, BOOKING, ATTENDANCE, makeEvent, makeStage, appendStage, today, dateText, money, stageCounts, eventCounts, needsAck, eventTime } from './domain.mjs';
import './styles.css';
import { apiRequest, assetUrl } from './transport.mjs';

const ICONS={Gamepad2,Utensils,Dices,ShoppingBag,Trees,Sparkles};
const TypeIcon=({type,size=20,...props})=>{const C=ICONS[TYPES[type]?.icon]||Sparkles;return <C size={size} {...props}/>;};
const timeAgo=value=>{const n=Math.max(0,Date.now()-Date.parse(value));return n<60000?'刚刚':n<3600000?`${Math.floor(n/60000)}分钟前`:n<86400000?`${Math.floor(n/3600000)}小时前`:new Intl.DateTimeFormat('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit',timeZone:'Asia/Shanghai'}).format(new Date(value));};
const sortEvents=events=>[...events].sort((a,b)=>(a.date+a.start).localeCompare(b.date+b.start));
const mapLink=stage=>stage.mapUrl||`https://uri.amap.com/search?keyword=${encodeURIComponent([stage.address,stage.location,stage.branch].filter(Boolean).join(' '))}&callnative=0`;
const coverImage=type=>assetUrl(['food','game','board','shopping'].includes(type)?'images/scenes.webp':'images/weekend.webp');

function Avatar({id,size=40,className=''}) {
  const m=member(id),i=Math.max(0,MEMBERS.findIndex(x=>x.id===id));
  if(!m)return <span className={'avatar avatar-anon '+className} style={{width:size,height:size}}><UserRound size={size*.5}/></span>;
  const hairs=['#3C4535','#6C4B35','#34465B','#62534D','#394A45','#7B4939'];
  return <span className={'avatar '+className} style={{width:size,height:size,background:m.color}} aria-hidden="true" title={m.name}>
    <svg viewBox="0 0 64 64" aria-hidden="true"><path d="M10 65Q10 45 32 45T54 65" fill={m.ink}/><path d="M25 42h14v12H25z" fill="#F3CBA9"/><ellipse cx="32" cy="31" rx="18" ry="20" fill="#F8D9B7"/><path d={i%3===0?'M13 31Q9 7 31 7Q54 5 52 33L44 23Q36 23 31 16Q27 27 13 31':i%3===1?'M13 33Q8 10 30 8Q54 5 52 31L45 25L40 15L31 24L24 18L18 33':'M13 30Q8 8 29 8Q51 3 52 31Q45 16 35 17L27 22L19 20L17 32'} fill={hairs[i]}/><circle cx="25" cy="32" r="1.6" fill="#343D38"/><circle cx="40" cy="32" r="1.6" fill="#343D38"/><path d="M29 40q3 3 6 0" fill="none" stroke="#9B6556" strokeWidth="1.6" strokeLinecap="round"/><ellipse cx="20" cy="37" rx="3.5" ry="1.6" fill="#EDAA96" opacity=".6"/><ellipse cx="45" cy="37" rx="3.5" ry="1.6" fill="#EDAA96" opacity=".6"/>{i===2&&<g fill="none" stroke="#345A8C" strokeWidth="1.3"><rect x="18" y="27" width="13" height="10" rx="4"/><rect x="34" y="27" width="13" height="10" rx="4"/><path d="M31 31h3"/></g>}{i===0&&<path d="M34 9Q35-1 45 3Q44 12 34 9" fill="#74A74C"/>}{i===1&&<path d="M12 17Q32-2 52 17v5H12z" fill="#D6A45B"/>}{i===3&&<g fill="#E58BA5"><circle cx="47" cy="19" r="5"/><circle cx="47" cy="19" r="2" fill="#F5D27B"/></g>}{i===4&&<path d="M15 17Q31-1 49 17" fill="none" stroke="#619A95" strokeWidth="7"/>}</svg>
  </span>;
}
function AvatarStack({ids,limit=4,size=28}){return <div className="avatar-stack" role="img" aria-label={'参与人员：'+ids.map(id=>member(id)?.name).join('、')}>{ids.slice(0,limit).map(id=><Avatar key={id} id={id} size={size}/>)}{ids.length>limit&&<span className="avatar more-avatar" style={{width:size,height:size}}>+{ids.length-limit}</span>}</div>;}
function StatusPill({status}){return <span className={'status status-'+status}><span className="status-dot"/>{STATUS[status]||status}</span>;}
function Empty({icon:Icon=Sprout,title,description,children}){return <div className="empty"><span className="empty-icon"><Icon size={32}/></span><h3>{title}</h3>{description&&<p>{description}</p>}{children}</div>;}
function Field({label,hint,children,className=''}){const id=useId();return <div className={'field '+className}><label htmlFor={id}>{label}</label>{React.isValidElement(children)&&!['div','fieldset'].includes(children.type)?React.cloneElement(children,{id}):children}{hint&&<span className="field-hint">{hint}</span>}</div>;}
function Modal({title,subtitle,children,onClose,wide=false}){
  const ref=useRef(),id=useId();
  useEffect(()=>{const previous=document.activeElement;const old=document.body.style.overflow;document.body.style.overflow='hidden';ref.current?.querySelector('button,input,textarea,select')?.focus();const key=e=>{if(e.key==='Escape')onClose();if(e.key==='Tab'){const elements=[...ref.current.querySelectorAll('button:not(:disabled),[href],input:not(:disabled),textarea:not(:disabled),select:not(:disabled),[tabindex="0"]')].filter(x=>x.getClientRects().length);const first=elements[0],last=elements.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}};document.addEventListener('keydown',key);return()=>{document.body.style.overflow=old;document.removeEventListener('keydown',key);previous?.focus();};},[]);
  return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)onClose();}}><section ref={ref} role="dialog" aria-modal="true" aria-labelledby={id} className={'modal '+(wide?'modal-wide':'')}><header className="modal-header"><div><h2 id={id}>{title}</h2>{subtitle&&<p>{subtitle}</p>}</div><button className="icon-btn" aria-label="关闭弹窗" onClick={onClose}><X size={22}/></button></header>{children}</section></div>;
}

function App(){
  const [data,setData]=useState({events:[],rsvps:[],comments:[],expenses:[],changes:[],acks:[],memberId:null});
  const [loading,setLoading]=useState(true),[loadError,setLoadError]=useState(''),[route,setRoute]=useState(location.hash.slice(1)||'home');
  const [modal,setModal]=useState(null),[toast,setToast]=useState(''),[busy,setBusy]=useState(false),[filter,setFilter]=useState('all'),[query,setQuery]=useState(''),[scheduleMember,setScheduleMember]=useState('all');
  const deferred=useRef(null),toastTimer=useRef();
  const current=data.memberId;
  const notify=message=>{setToast(message);clearTimeout(toastTimer.current);toastTimer.current=setTimeout(()=>setToast(''),4000);};
  const load=async(initial=false)=>{try{const r=await apiRequest('/api/state');if(!r.ok)throw new Error('数据加载失败');setData(await r.json());setLoadError('');}catch(e){if(initial)setLoadError(e.message==='共享服务尚未连接，请联系网站管理员配置后重试。'?e.message:'暂时无法连接共享服务，请检查网络后重试。');}finally{if(initial)setLoading(false);}};
  useEffect(()=>{load(true);const interval=setInterval(()=>{if(document.visibilityState==='visible')load();},20000);return()=>clearInterval(interval);},[]);
  useEffect(()=>{const update=()=>{setRoute(location.hash.slice(1)||'home');window.scrollTo({top:0,behavior:'instant'});};addEventListener('hashchange',update);return()=>removeEventListener('hashchange',update);},[]);
  const go=next=>{if(location.hash==='#'+next)window.scrollTo({top:0,behavior:'smooth'});else location.hash=next;};
  async function mutate(url,method='POST',body={},message='已保存'){setBusy(true);try{const response=await apiRequest(url,{method,headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const result=await response.json();if(!response.ok)throw new Error(result.error||'操作失败');await load();if(message)notify(message);return result;}catch(e){notify(e.message);return null;}finally{setBusy(false);}}
  function needIdentity(callback){if(current)callback();else{deferred.current=callback;setModal({type:'identity'});}}
  function create(type='food'){needIdentity(()=>setModal({type:'create',template:type}));}
  const selectedEvent=route.startsWith('event/')?data.events.find(e=>e.id===decodeURIComponent(route.slice(6))):null;
  const pendingEvents=data.events.filter(e=>needsAck(e,current,data.rsvps,data.acks));
  const notifications=[...data.changes.map(c=>({...c,kind:'change'})),...data.comments.filter(c=>!c.deleted&&c.memberId!==current).map(c=>({...c,kind:'comment'}))].sort((a,b)=>b.createdAt.localeCompare(a.createdAt));
  const [readAt,setReadAt]=useState(()=>localStorage.getItem('cg-read-at')||'');
  const unread=notifications.filter(n=>n.createdAt>readAt).length+pendingEvents.length;
  const share=async e=>{const url=location.origin+location.pathname+'#event/'+encodeURIComponent(e.id);try{if(navigator.share)await navigator.share({title:e.title,text:'一起凑个局，安排和报名都在这里。',url});else{await navigator.clipboard.writeText(url);notify('活动链接已复制，发给小队吧');}}catch(err){if(err.name!=='AbortError')setModal({type:'share',url});}};
  const eventProps={data,current,go,create,notify};
  return <>
    <header className="site-header"><div className="header-inner"><a href="#home" className="brand" aria-label="凑个局首页"><span className="brand-mark"><Sprout size={25} strokeWidth={2}/></span><span>凑个局<span className="brand-dot">.</span></span><small>GOOD TIMES CLUB</small></a><nav className="desktop-nav" aria-label="主导航">{[['home','活动广场'],['schedule','我的日程'],['team','小队成员']].map(([key,label])=><a href={'#'+key} className={route===key?'active':''} aria-current={route===key?'page':undefined} key={key}>{label}</a>)}</nav><div className="header-actions"><button className="icon-btn notification-button" aria-label={`通知${unread?'，'+unread+'条未读':''}`} onClick={()=>setModal({type:'notifications'})}><Bell size={21}/>{unread>0&&<span className="notification-dot"/>}</button><span className="header-divider"/><button className="identity-btn" onClick={()=>setModal({type:'identity'})}><Avatar id={current} size={32}/><span>{member(current)?.name||'选择身份'}</span><ChevronDown size={14}/></button></div></div></header>
    <main className={'page '+(selectedEvent?'detail-page':'')}>
      {loading?<div className="loading-state"><LoaderCircle className="spin"/><p>正在召集好时光…</p></div>:loadError?<Empty icon={Cloud} title="信号暂时走丢了" description={loadError}><button className="btn primary" onClick={()=>{setLoading(true);load(true);}}>重新加载</button></Empty>:<>
        {route==='home'&&<>
          <section className="hero"><div className="hero-art"><img src={assetUrl('images/weekend.webp')} alt="四位男生和两位女生在湖畔树荫下野餐的动漫插画" fetchPriority="high"/></div><div className="hero-copy"><span className="eyebrow"><span/><Sun size={15}/> 六个人，也有一整个小世界</span><h1>把「下次一定」，<br/>变成<span className="hero-emphasis">这次见面<svg viewBox="0 0 200 12" aria-hidden="true"><path d="M3 8Q94-1 195 6M14 11Q105 3 185 9" stroke="#94BC69" strokeWidth="3" fill="none" strokeLinecap="round"/></svg></span>。</h1><p>一起吃饭、玩游戏，认真浪费好时光。<br className="desktop-only"/>我们的下一次见面，从这里开始。</p><button className="btn primary hero-cta" onClick={()=>create('food')}><Plus size={19}/>发起一个局<ArrowUpRight size={18}/></button><div className="hero-foot"><span className="tiny-spark">✧</span>计划不用完美，见面就很美好</div></div><span className="hero-stamp" aria-hidden="true">LET’S<br/>HANG OUT!<span>✳</span></span></section>
          <section className="templates-section" aria-labelledby="templates-heading"><div className="section-heading"><div><h2 id="templates-heading">今天，想凑个什么局？<span className="heading-spark">✧</span></h2><p>选个模板，把好主意变成好安排。</p></div><button className="text-btn desktop-only" onClick={()=>create('custom')}>自由发挥<ArrowRight size={16}/></button></div><div className="template-grid">{['food','game','board','shopping'].map(type=><button key={type} className={'template template-'+type} onClick={()=>create(type)}><span className="template-icon" style={{background:TYPES[type].color,color:TYPES[type].ink}}><TypeIcon type={type} size={29}/><span className="icon-spark">✦</span></span><span className="template-text"><strong>{TYPES[type].name}</strong><small>{TYPES[type].tagline}</small></span><ArrowUpRight className="template-arrow" size={18}/></button>)}</div></section>
          <div className="home-columns"><section className="activities-section"><div className="section-heading"><div className="heading-inline"><h2>下一次见面</h2><span className="count-badge">{data.events.length}</span></div><button className="text-btn" onClick={()=>create('custom')}><Plus size={16}/>发起活动</button></div><div className="filter-toolbar"><div className="filter-tabs" aria-label="活动状态">{[['all','全部活动'],['planning','征询中'],['confirmed','已定案'],['ended','已结束']].map(([key,label])=><button className={filter===key?'selected':''} aria-pressed={filter===key} onClick={()=>setFilter(key)} key={key}>{label}</button>)}</div><label className="search-field"><Search size={17}/><input aria-label="搜索活动" placeholder="找个局…" value={query} onChange={e=>setQuery(e.target.value)}/>{query&&<button aria-label="清空搜索" onClick={()=>setQuery('')}><X size={14}/></button>}</label></div><div className="activity-grid">{sortEvents(data.events.filter(e=>(filter==='all'||e.status===filter)&&[e.title,TYPES[e.type]?.name,...e.stages.map(s=>s.location)].join(' ').includes(query))).map(e=><EventCard key={e.id} event={e} {...eventProps}/>)}</div>{!data.events.some(e=>(filter==='all'||e.status===filter)&&[e.title,TYPES[e.type]?.name,...e.stages.map(s=>s.location)].join(' ').includes(query))&&<Empty title="这里还没有成形的计划" description="换个筛选看看，或者自己发起一个局。"><button className="btn secondary" onClick={()=>create('custom')}>发起活动<Plus size={17}/></button></Empty>}<p className="list-note"><Sprout size={14}/> 示例活动用于体验流程，真实活动由你们发起。</p></section>
          <aside className="home-sidebar"><section className="team-panel"><div className="panel-title"><span className="mini-eyebrow">OUR LITTLE CREW</span><button className="icon-btn small" aria-label="查看小队" onClick={()=>go('team')}><ArrowUpRight size={18}/></button></div><h3>熟悉的人，新的故事<span>✦</span></h3><p className="muted">6 位伙伴 · 4 位男生 · 2 位女生</p><div className="crew-grid">{MEMBERS.map(m=><button key={m.id} className={'crew-person '+(current===m.id?'is-me':'')} onClick={()=>{setScheduleMember(m.id);go('schedule');}}><Avatar id={m.id} size={48}/><span>{m.name}{current===m.id&&<small>我</small>}</span></button>)}</div><button className="team-link" onClick={()=>setModal({type:'identity'})}>{current?'切换我的身份':'先选一下，你是哪位？'}<ArrowRight size={16}/></button></section><section className="little-note"><span className="note-pin"/><span className="mini-eyebrow">A LITTLE REMINDER</span><h3>时间、地点、结束时间，<br/>说清楚才好安心赴约。</h3><p>大家的想法，放进评论里。<br/>确定的安排，放进行程里。</p><span className="note-doodle"><Coffee size={34}/><Heart size={16}/></span></section><div className="sync-status"><span/>活动数据自动同步<small>每 20 秒更新</small></div></aside></div>
        </>}
        {route.startsWith('event/')&&(selectedEvent?<EventDetail event={selectedEvent} {...eventProps} mutate={mutate} busy={busy} needIdentity={needIdentity} edit={()=>setModal({type:'create',event:selectedEvent})} join={()=>needIdentity(()=>setModal({type:'rsvp',event:selectedEvent}))} addExpense={()=>needIdentity(()=>setModal({type:'expense',event:selectedEvent}))} share={()=>share(selectedEvent)} confirmDelete={()=>setModal({type:'deleteEvent',event:selectedEvent})}/>:<Empty title="这个活动暂时找不到" description="它可能已被删除，回广场看看其他计划吧。"><button className="btn primary" onClick={()=>go('home')}>回活动广场</button></Empty>)}
        {route==='schedule'&&<Schedule {...eventProps} selectedMember={scheduleMember} setSelectedMember={setScheduleMember}/>}
        {route==='team'&&<Team {...eventProps} onView={id=>{setScheduleMember(id);go('schedule');}}/>}
        {route==='profile'&&<Profile {...eventProps} chooseIdentity={()=>setModal({type:'identity'})} pendingEvents={pendingEvents}/>}
      </>}
    </main>
    {!loading&&!selectedEvent&&<footer className="site-footer"><span className="footer-logo"><Sprout size={17}/>凑个局</span><p>周末很短，和喜欢的人见面要紧。</p><small>© 2026 GOOD TIMES CLUB</small></footer>}
    {!selectedEvent&&<nav className="bottom-nav" aria-label="移动端导航">{[['home',Home,'活动'],['schedule',CalendarDays,'日程'],['create',Plus,'发起'],['team',Users,'小队'],['profile',UserRound,'我的']].map(([key,Icon,label])=><button key={key} className={(route===key?'active ':'')+(key==='create'?'nav-create':'')} aria-current={route===key?'page':undefined} onClick={()=>key==='create'?create('food'):go(key)}><span><Icon size={22}/></span><small>{label}</small></button>)}</nav>}
    {toast&&<div className="toast" role="status"><CircleCheck size={18}/>{toast}</div>}
    {modal?.type==='identity'&&<Modal title="嗨，你是哪位伙伴？" subtitle="选好身份，就可以报名、评论和一起做计划。" onClose={()=>{deferred.current=null;setModal(null);}}><div className="identity-grid">{MEMBERS.map(m=><button key={m.id} disabled={busy} className={'identity-option '+(current===m.id?'selected':'')} onClick={async()=>{const result=await mutate('/api/identity','POST',{memberId:m.id},`嗨，${m.name}！下次见面一起安排。`);if(result){const cb=deferred.current;deferred.current=null;setModal(null);cb?.();}}}><Avatar id={m.id} size={64}/><strong>{m.name}</strong>{current===m.id&&<Check className="identity-check" size={18}/>}</button>)}</div><p className="modal-footnote"><Users size={15}/>我们的小队：4 位男生，2 位女生</p></Modal>}
    {modal?.type==='create'&&<Modal wide title={modal.event?'编辑活动安排':'发起一个新计划'} subtitle={modal.event?'重要安排变更后，参与者需要重新确认。':'先定个大概，剩下的和大家一起商量。'} onClose={()=>setModal(null)}><EventForm key={modal.event?.id||modal.template} initial={modal.event} template={modal.template} current={current} busy={busy} onClose={()=>setModal(null)} onSave={async(value)=>{const result=await mutate(modal.event?'/api/events/'+modal.event.id:'/api/events',modal.event?'PUT':'POST',value,modal.event?'安排已更新，已记录变更':'新计划已创建，邀请大家来吧');if(result){setModal(null);go('event/'+(modal.event?.id||result.id));}}}/></Modal>}
    {modal?.type==='rsvp'&&<Modal wide title="这次，你怎么参加？" subtitle="可以只参加一段，也可以一起待到最后。" onClose={()=>setModal(null)}><RsvpForm event={modal.event} data={data} current={current} busy={busy} onClose={()=>setModal(null)} onSave={async value=>{const result=await mutate('/api/events/'+modal.event.id+'/rsvp','POST',value,'报名已更新，大家都能看到你的安排了');if(result)setModal(null);}}/></Modal>}
    {modal?.type==='expense'&&<Modal title="记一笔共同开销" subtitle="按实际参与人员分摊，金额精确到分。" onClose={()=>setModal(null)}><ExpenseForm event={modal.event} current={current} data={data} busy={busy} onClose={()=>setModal(null)} onSave={async value=>{if(await mutate('/api/events/'+modal.event.id+'/expenses','POST',value,'费用已记下'))setModal(null);}}/></Modal>}
    {modal?.type==='deleteEvent'&&<Modal title="删除这个活动？" subtitle="活动的报名、评论和费用记录也会一并删除。" onClose={()=>setModal(null)}><div className="confirm-body"><p>将删除「{modal.event.title}」。</p><div className="form-actions"><button className="btn ghost" onClick={()=>setModal(null)}>保留活动</button><button className="btn danger" disabled={busy} onClick={async()=>{if(await mutate('/api/events/'+modal.event.id,'DELETE',{},'活动已删除')){setModal(null);go('home');}}}>确认删除</button></div></div></Modal>}
    {modal?.type==='notifications'&&<Modal title="小队的新消息" subtitle="安排有变化、有人提想法，都在这里。" onClose={()=>setModal(null)}><div className="notification-list">{pendingEvents.map(e=><button key={e.id} className="notification-item important" onClick={()=>{setModal(null);go('event/'+e.id);}}><AlertCircle size={22}/><div><strong>有新版安排等你确认</strong><p>{e.title} · 第 {e.version} 版</p></div><ChevronRight size={18}/></button>)}{notifications.slice(0,30).map(n=><button key={n.id} className={'notification-item '+(n.createdAt>readAt?'unread':'')} onClick={()=>{setModal(null);go('event/'+n.eventId);}}><Avatar id={n.memberId} size={36}/><div><strong>{member(n.memberId)?.name}{n.kind==='change'?'更新了安排':'发表了想法'}</strong><p>{n.text}</p><small>{timeAgo(n.createdAt)}</small></div></button>)}{!notifications.length&&!pendingEvents.length&&<Empty icon={Bell} title="暂时没有新消息" description="有新安排时，会在这里告诉你。"/>}</div><div className="modal-bottom"><button className="btn secondary full" onClick={()=>{const value=new Date().toISOString();localStorage.setItem('cg-read-at',value);setReadAt(value);notify('消息已标为已读，重要安排仍需单独确认');}}><CheckCheck size={18}/>消息全部已读</button></div></Modal>}
    {modal?.type==='share'&&<Modal title="把活动分享给伙伴" onClose={()=>setModal(null)}><div className="modal-bottom"><Field label="长按或选中复制活动链接"><input value={modal.url} readOnly onFocus={e=>e.target.select()}/></Field></div></Modal>}
  </>;
}

function EventCard({event:e,data,current,go}){
  const counts=eventCounts(e,data.rsvps),type=TYPES[e.type]||TYPES.custom,comments=data.comments.filter(c=>c.eventId===e.id&&!c.deleted).length;
  const cost=e.stages.reduce((n,s)=>n+s.budget,0);
  return <article className="activity-card"><a href={'#event/'+e.id} className={'card-image card-image-'+e.type}><img src={coverImage(e.type)} alt={e.type==='outdoor'?'阳光下的湖畔野餐':type.name+'场景插画'} loading="lazy"/><span className="image-type"><TypeIcon type={e.type} size={14}/>{type.name}</span><span className="image-date"><CalendarDays size={14}/>{e.date.slice(5).replace('-','/')}</span>{e.isDemo&&<span className="demo-badge">示例活动</span>}</a><div className="card-topline"><StatusPill status={e.status}/><span>{e.stages.length>1?`${e.stages.length} 个环节 · 可分段参加`:type.tagline}</span></div><h3><a href={'#event/'+e.id}>{e.title}</a></h3><div className="card-meta"><span><CalendarDays size={15}/>{dateText(e.date)}<i>·</i>{e.start}–{e.end}</span><span><MapPin size={15}/>{[e.stages[0]?.location,e.stages[0]?.branch].filter(Boolean).join(' · ')||'地点一起商量'}</span></div><div className="card-bottom"><div><AvatarStack ids={counts.people}/><span>{counts.yes?`${counts.yes} 人确认`:'等你来加入'}{counts.maybe>0&&<small> · {counts.maybe} 待定</small>}</span></div><span className="card-comment"><MessageCircle size={16}/>{comments||'聊聊'}</span></div><a href={'#event/'+e.id} className="card-more" aria-label={'查看'+e.title}>看看安排<ArrowRight size={15}/></a></article>;
}

function EventDetail({event:e,data,current,go,mutate,busy,needIdentity,edit,join,addExpense,share,confirmDelete}){
  const [tab,setTab]=useState('itinerary');
  useEffect(()=>setTab('itinerary'),[e.id]);
  const counts=eventCounts(e,data.rsvps),mine=data.rsvps.filter(r=>r.eventId===e.id&&r.memberId===current),isOwner=e.creator===current;
  const comments=data.comments.filter(c=>c.eventId===e.id),expenses=data.expenses.filter(x=>x.eventId===e.id),changes=data.changes.filter(c=>c.eventId===e.id).sort((a,b)=>b.version-a.version);
  const pending=needsAck(e,current,data.rsvps,data.acks), totalBudget=e.stages.reduce((n,s)=>n+s.budget,0);
  const closed=['draft','ended','cancelled'].includes(e.status),deadlinePassed=e.deadline&&Date.now()>Date.parse(e.deadline+'+08:00');
  const joinLabel=closed?'报名已关闭':mine.length?'更新我的报名':deadlinePassed?'查看报名与到场':'我要参加';
  return <><div className="detail-breadcrumb"><button className="text-btn" onClick={()=>go('home')}><ArrowLeft size={17}/>活动广场</button><span>/</span><span>{TYPES[e.type]?.name}</span><div className="detail-tools"><button className="icon-btn" aria-label="分享活动" onClick={share}><Share2 size={19}/></button>{(isOwner||e.isDemo)&&<button className="icon-btn" aria-label="删除活动" onClick={confirmDelete}><Trash2 size={18}/></button>}</div></div><div className={'detail-cover detail-cover-'+e.type}><img src={coverImage(e.type)} alt={TYPES[e.type]?.name+'活动插画'}/><span className="cover-caption"><TypeIcon type={e.type} size={17}/>{TYPES[e.type]?.tagline}</span></div><div className="detail-layout"><div className="detail-main"><div className="detail-intro"><div className="detail-labels"><StatusPill status={e.status}/>{e.isDemo&&<span className="tag">示例活动 · 可体验</span>}<span className="muted">第 {e.version} 版安排</span></div><h1>{e.title}</h1><div className="organizer"><Avatar id={e.creator} size={28}/><span>{member(e.creator)?.name} 发起</span><span>·</span><span>{e.invitees.length} 位受邀伙伴</span>{isOwner&&<button className="text-btn" onClick={edit}><Pencil size={15}/>编辑安排</button>}</div><p className="detail-description">{e.description||'有空就聚一聚，具体安排一起商量。'}</p><div className="detail-facts"><div><CalendarDays size={21}/><span><small>活动日期 · 北京时间</small><strong>{dateText(e.date,true)}</strong></span></div><div><Clock3 size={21}/><span><small>整体起止 · 含交通与休息</small><strong>{eventTime(e)}</strong></span></div><div><MapPin size={21}/><span><small>首个集合地点</small><strong>{e.stages[0]?.meetup||[e.stages[0]?.location,e.stages[0]?.branch].filter(Boolean).join(' · ')||'待商量'}</strong></span></div><div><Wallet size={21}/><span><small>预计人均 · {e.currency}</small><strong>{totalBudget?money(totalBudget,e.currency):'暂未设置预算'}</strong></span></div></div></div>
      {pending&&<div className="notice warning"><AlertCircle size={21}/><div><strong>安排有更新，请确认第 {e.version} 版</strong><p>请查看最新时间、地点与行程，确认后大家才知道你已收到。</p></div><button className="btn secondary" disabled={busy} onClick={()=>mutate('/api/events/'+e.id+'/ack','POST',{version:e.version},'已确认最新安排')}>我已确认</button></div>}
      <div className="detail-tabs" role="tablist" aria-label="活动详情">{[['itinerary',Route,'行程'],['members',Users,'人员'],['discussion',MessageCircle,'讨论'],['expenses',Wallet,'费用']].map(([key,Icon,label])=><button role="tab" aria-selected={tab===key} aria-controls={'panel-'+key} id={'tab-'+key} className={tab===key?'active':''} key={key} onClick={()=>setTab(key)}><Icon size={18}/>{label}{key==='discussion'&&comments.filter(c=>!c.deleted).length>0&&<small>{comments.filter(c=>!c.deleted).length}</small>}</button>)}</div>
      <section className="tab-panel" role="tabpanel" id={'panel-'+tab} aria-labelledby={'tab-'+tab}>
        {tab==='itinerary'&&<><div className="section-heading"><h2>把这一天，慢慢安排好</h2><span className="muted">{e.stages.length} 个环节</span></div><div className="timeline">{e.stages.map((s,i)=><Stage key={s.id} stage={s} index={i} event={e} data={data} mutate={mutate} busy={busy}/>)}</div>{changes.length>0&&<details className="change-log"><summary><Clock3 size={17}/>安排变更记录<span>{changes.length} 次</span><ChevronDown size={17}/></summary>{changes.map(c=><div className="change-item" key={c.id}><span>V{c.version}</span><div><strong>{c.text}</strong><small>{member(c.memberId)?.name} · {timeAgo(c.createdAt)}</small></div></div>)}</details>}</>}
        {tab==='members'&&<><div className="section-heading"><div><h2>这次，谁一起？</h2><p>邀请不等于确认，人数按每个环节分别统计。</p></div></div>{e.stages.map(s=>{const c=stageCounts(e,s.id,data.rsvps);return <div className="member-stage" key={s.id}><div className="member-stage-heading"><h3><TypeIcon type={s.type}/>{s.title}</h3><span>{c.yes} 人确认{c.guests>0?` + ${c.guests} 位同行者`:''} · {c.maybe} 待定</span></div>{e.invitees.map(id=>{const r=data.rsvps.find(r=>r.eventId===e.id&&r.stageId===s.id&&r.memberId===id);return <div className="member-row" key={id}><Avatar id={id} size={38}/><div className="member-row-name"><strong>{member(id)?.name}{id===current&&<small>我</small>}</strong><span>{r?.status==='yes'?[r.eta&&`预计 ${r.eta} 到`,r.leave&&`${r.leave} 离开`,r.transport].filter(Boolean).join(' · ')||'到达时间待更新':r?.status==='maybe'?'还在协调时间':'等待本人回应'}</span>{r?.guests?.length>0&&<span>同行：{r.guests.join('、')}</span>}{r?.needs&&(current===id||isOwner||s.leader===current)&&<span className="member-needs">个人需求：{r.needs}</span>}</div><div className="member-row-status"><span className={'rsvp-label rsvp-'+(r?.status||'pending')}>{RSVP[r?.status||'pending']}</span>{r?.status==='yes'&&<small>{ATTENDANCE[r.attendance]||'未出发'}</small>}</div></div>;})}</div>})}</>}
        {tab==='discussion'&&<Discussion event={e} comments={comments} current={current} mutate={mutate} busy={busy} needIdentity={needIdentity}/>}
        {tab==='expenses'&&<><div className="section-heading"><div><h2>开心聚，也清楚算</h2><p>按环节、按实际参与人员分摊。</p></div><button className="btn secondary" onClick={addExpense}><Plus size={17}/>记一笔</button></div><div className="expense-overview"><div><span>预计人均预算</span><strong>{money(totalBudget,e.currency)}</strong></div><div><span>已记录总支出</span><strong>{money(expenses.reduce((n,x)=>n+x.amount,0),e.currency)}</strong></div></div>{!expenses.length?<Empty icon={Wallet} title="账本还是空的" description="有人垫付后记一笔，大家一起把账算清楚。"/>:expenses.map(x=><div className="expense-card" key={x.id}><div className="expense-header"><div><strong>{x.title}</strong><p>{e.stages.find(s=>s.id===x.stageId)?.title} · {member(x.payer)?.name} 垫付</p></div><strong>{money(x.amount,e.currency)}</strong>{[x.createdBy,e.creator].includes(current)&&<button className="icon-btn" aria-label={'删除费用'+x.title} onClick={()=>{if(window.confirm('删除这笔费用记录？'))mutate('/api/events/'+e.id+'/expenses/'+x.id,'DELETE',{},'费用已删除');}}><Trash2 size={16}/></button>}</div><div className="expense-shares">{x.shares.map(s=><div key={s.memberId}><Avatar id={s.memberId} size={26}/><span>{member(s.memberId)?.name}</span><strong>{money(s.amount,e.currency)}</strong>{s.memberId===x.payer?<span className="settled">已垫付</span>:<><span className={x.settled.includes(s.memberId)?'settled':'muted'}>{x.settled.includes(s.memberId)?'已结清':'待结算'}</span>{s.memberId===current&&<button className="text-btn" disabled={busy} onClick={()=>mutate('/api/events/'+e.id+'/expenses/'+x.id,'PUT',{settled:!x.settled.includes(current)},'结算状态已更新')}>{x.settled.includes(current)?'撤销':'我已结清'}</button>}</>}</div>)}</div><small className="muted">同行者份额计入主报名人；结清状态由本人登记。</small></div>)}</>}
      </section></div><aside className="detail-aside"><section className="join-panel"><span className="mini-eyebrow">SEE YOU SOON</span><h3>{counts.yes?'熟悉的面孔，等你加入':'好时光，还差一个你'}</h3><AvatarStack ids={counts.people} limit={6} size={40}/><div className="join-counts"><div><strong>{counts.yes}</strong><small>确认参加</small></div><div><strong>{counts.maybe}</strong><small>还在待定</small></div><div><strong>{counts.pending}</strong><small>等待回应</small></div></div><button className="btn primary full" disabled={closed} onClick={join}><Check size={18}/>{joinLabel}</button>{isOwner&&<button className="btn secondary full" onClick={edit}><Pencil size={16}/>管理活动安排</button>}<p className="join-help">{e.deadline?`报名截止：${e.deadline.replace('T',' ')}`:'时间还没确定？先选「待定」也可以。'}</p>{e.status==='planning'&&<div className="soft-note"><CircleHelp size={17}/>当前方案仍在征询，定案后请再确认安排。</div>}</section><section className="detail-side-note"><Sprout size={23}/><p>可以只参加一个环节，<br/>也可以早点回家。<br/><strong>舒服地见面，最重要。</strong></p></section></aside></div><div className="mobile-join-bar"><div><strong>{counts.yes} 人确认参加</strong><small>{e.stages.length} 个环节 · 可分段报名</small></div><button className="btn primary" disabled={closed} onClick={join}>{joinLabel}<ArrowRight size={17}/></button></div></>;
}

function Stage({stage:s,event:e,data,index,mutate,busy}){
  const [bookingOpen,setBookingOpen]=useState(false);
  const counts=stageCounts(e,s.id,data.rsvps),duration=Math.round((Date.parse(`${s.endDate||s.date||e.date}T${s.end}:00+08:00`)-Date.parse(`${s.date||e.date}T${s.start}:00+08:00`))/60000);
  return <article className="timeline-item"><div className="timeline-rail"><span className="timeline-number">{String(index+1).padStart(2,'0')}</span></div><div className="stage-content"><div className="stage-top"><span className="stage-time">{s.start} — {s.end}</span><span className="muted">{duration>=60?`${Math.floor(duration/60)} 小时${duration%60?' '+duration%60+' 分钟':''}`:`${duration} 分钟`}</span></div><h3><TypeIcon type={s.type} size={21}/>{s.title}</h3><div className="stage-location"><MapPin size={17}/><strong>{s.location||'地点待商量'}{s.branch&&<span className="branch-label">{s.branch}</span>}</strong>{s.location&&s.location!=='线上集合'&&<a href={mapLink(s)} target="_blank" rel="noopener noreferrer" aria-label={'地图查看'+s.location}>地图<ArrowUpRight size={14}/></a>}</div>{s.address&&<p className="stage-sub">{s.address}</p>}{s.meetup&&<div className="stage-meetup"><Flag size={16}/><span>集合点：{s.meetup}</span></div>}{s.notes&&<p className="stage-notes">{s.notes}</p>}
    {s.bookingMode!=='none'&&<div className="booking-info"><span><ShieldCheck size={16}/>{s.bookingMode==='queue'?'现场排队':'商家预约'}</span>{s.bookingMode==='reservation'?<strong>{BOOKING[s.bookingStatus]||'待处理'}{s.bookingRef&&` · ${s.bookingRef}`}</strong>:<strong>{({not_taken:'尚未取号',waiting:'排队中',called:'已叫号',seated:'已入场',abandoned:'已放弃'})[s.queueStatus]||'尚未取号'}{s.queueNumber&&` · ${s.queueNumber}`}{s.waitMinutes&&` · 预计等待 ${s.waitMinutes} 分钟`}</strong>}{s.queueUpdatedAt&&<small>更新于 {s.queueUpdatedAt.replace('T',' ')}</small>}</div>}
    {s.bookingMode!=='none'&&[e.creator,s.leader].includes(data.memberId)&&<><button className="text-btn booking-update" onClick={()=>setBookingOpen(!bookingOpen)}><Pencil size={14}/>{bookingOpen?'收起预约更新':'更新预约 / 排队'}</button>{bookingOpen&&<BookingForm stage={s} busy={busy} onSave={async value=>{if(await mutate('/api/events/'+e.id+'/booking/'+s.id,'POST',{...value,version:e.version},'预约进度已更新'))setBookingOpen(false);}}/>}</>}
    {(s.route||s.distance||s.gameName||s.restPoints||s.exitPoints)&&<div className="stage-extra">{s.gameName&&<p><strong>{s.type==='board'?'桌游':'游戏'}</strong>{s.gameName}{s.platform&&` · ${s.platform}`}</p>}{s.experience&&<p><strong>参与说明</strong>{s.experience}</p>}{s.route&&<p><strong>计划路线</strong>{s.route}</p>}{s.distance&&<p><strong>路线强度</strong>{s.distance} km{s.elevation&&` · 爬升 ${s.elevation} m`}{s.transportMinutes&&` · 交通约 ${s.transportMinutes} 分钟`}</p>}{s.restPoints&&<p><strong>休息点</strong>{s.restPoints}</p>}{s.exitPoints&&<p><strong>退出点</strong>{s.exitPoints}</p>}</div>}
    <div className="stage-footer"><span><Users size={15}/>{counts.yes} 人确认{counts.guests?` + ${counts.guests} 同行`:''}{s.capacity?` / 容量 ${s.capacity}`:''}</span>{s.leader&&<span><Avatar id={s.leader} size={23}/>{member(s.leader)?.name} 负责</span>}<span>{s.budget?money(s.budget,e.currency)+'/人':'预算待补充'}</span></div>{s.capacity&&counts.yes+counts.guests>s.capacity?<p className="inline-warning"><AlertCircle size={15}/>报名人数超过预约容量，请负责人重新确认。</p>:null}</div></article>;
}

function BookingForm({stage:s,busy,onSave}){
  const [v,setV]=useState({...s});const set=(k,value)=>setV(old=>({...old,[k]:value}));
  return <form className="booking-edit-form" onSubmit={ev=>{ev.preventDefault();const now=new Date();const date=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(now);const time=new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Shanghai',hour:'2-digit',minute:'2-digit'}).format(now);onSave({...v,queueUpdatedAt:date+'T'+time});}}>{s.bookingMode==='reservation'?<><Field label="预约结果"><select value={v.bookingStatus} onChange={ev=>set('bookingStatus',ev.target.value)}>{Object.entries(BOOKING).map(([k,label])=><option key={k} value={k}>{label}</option>)}</select></Field><Field label="预约编号 / 确认依据"><input value={v.bookingRef} onChange={ev=>set('bookingRef',ev.target.value)}/></Field></>:<><Field label="排队状态"><select value={v.queueStatus} onChange={ev=>set('queueStatus',ev.target.value)}><option value="not_taken">尚未取号</option><option value="waiting">排队中</option><option value="called">已叫号</option><option value="seated">已入场</option><option value="abandoned">已放弃</option></select></Field><div className="form-grid"><Field label="排队号码"><input value={v.queueNumber} onChange={ev=>set('queueNumber',ev.target.value)}/></Field><Field label="预计等待（分钟）"><input type="number" min="0" value={v.waitMinutes} onChange={ev=>set('waitMinutes',ev.target.value)}/></Field></div></>}<button className="btn secondary" disabled={busy} type="submit"><Check size={15}/>保存进度</button></form>;
}

function Discussion({event:e,comments,current,mutate,busy,needIdentity}){
  const [value,setValue]=useState(''),[reply,setReply]=useState(null),[editing,setEditing]=useState(null);const input=useRef();
  const submit=async ev=>{ev.preventDefault();if(!current){needIdentity(()=>{});return;}if(!value.trim())return;const result=await mutate('/api/events/'+e.id+'/comments'+(editing?'/'+editing:''),editing?'PUT':'POST',{text:value,parentId:reply?.id||null},editing?'评论已更新':'想法已发出，让大家一起聊聊');if(result){setValue('');setReply(null);setEditing(null);}};
  function renderComment(c,depth=0){return <div className={'comment '+(depth?'comment-reply':'')} key={c.id}><Avatar id={c.memberId} size={depth?30:38}/><div className="comment-content"><div className="comment-author"><strong>{member(c.memberId)?.name}</strong>{c.memberId===e.creator&&<span className="owner-tag">组织者</span>}<time>{timeAgo(c.createdAt)}</time></div><p className={c.deleted?'deleted-comment':''}>{c.text}</p>{c.editedAt&&<small className="muted">已编辑</small>}{!c.deleted&&<><div className="comment-actions"><button onClick={()=>{setReply(c);setEditing(null);input.current?.focus();}}><MessageCircle size={14}/>回复</button>{c.memberId===current&&<button onClick={()=>{setEditing(c.id);setValue(c.text);setReply(null);input.current?.focus();}}><Pencil size={13}/>编辑</button>}{[c.memberId,e.creator].includes(current)&&<button disabled={busy} onClick={()=>{if(window.confirm('删除这条评论？'))mutate('/api/events/'+e.id+'/comments/'+c.id,'DELETE',{},'评论已删除');}}>删除</button>}{e.creator===current&&!c.parentId&&<select aria-label="建议处理状态" value={c.status} disabled={busy} onChange={ev=>mutate('/api/events/'+e.id+'/comments/'+c.id,'PUT',{status:ev.target.value},'建议状态已更新')}><option value="discussion">待讨论</option><option value="accepted">已采纳</option><option value="rejected">暂不采纳</option></select>}</div>{c.status==='accepted'&&<span className="suggestion-status"><Check size={13}/>已采纳 · 正式安排请看行程</span>}{c.status==='rejected'&&<span className="suggestion-status neutral">暂不采纳</span>}</>}{comments.filter(x=>x.parentId===c.id).map(x=>renderComment(x,depth+1))}</div></div>;}
  return <><div className="section-heading"><div><h2>好主意，一起聊出来</h2><p>所有伙伴都可以评论，待定也能提想法。</p></div><span className="count-badge">{comments.filter(c=>!c.deleted).length}</span></div><div className="soft-note discussion-note"><Info size={17}/>讨论中的建议由组织者采纳并更新行程后，成为正式安排。</div><form className="comment-composer" onSubmit={submit}><div className="composer-head"><Avatar id={current} size={32}/><span>{member(current)?.name||'选个身份，加入讨论'}</span></div>{(reply||editing)&&<div className="reply-label"><span>{editing?'正在编辑自己的评论':`回复 ${member(reply.memberId)?.name}：${reply.text.slice(0,40)}`}</span><button type="button" aria-label="取消回复或编辑" onClick={()=>{setReply(null);setEditing(null);setValue('');}}><X size={15}/></button></div>}<label className="sr-only" htmlFor="comment-input">你的想法</label><textarea id="comment-input" ref={input} maxLength={2000} placeholder="推荐一家店？想换个时间？或者只是说一句：我来！" value={value} onChange={ev=>setValue(ev.target.value)}/><div className="composer-bottom"><small>{value.length}/2000</small><button className="btn primary" disabled={busy||(!value.trim()&&!!current)} type="submit"><Send size={16}/>{editing?'保存修改':'发送想法'}</button></div></form><div className="comments-list">{comments.length?comments.filter(c=>!c.parentId).sort((a,b)=>a.createdAt.localeCompare(b.createdAt)).map(c=>renderComment(c)):<Empty icon={MessageCircle} title="第一条想法，等你来写" description="一句“我想去”，也能让计划更近一点。"/>}</div></>;
}

function EventForm({initial,template,current,busy,onSave,onClose}){
  const [value,setValue]=useState(()=>initial?structuredClone(initial):makeEvent(template||'food',current));const [error,setError]=useState('');
  const set=(key,v)=>setValue(old=>({...old,[key]:v}));
  const stageSet=(id,key,v)=>setValue(old=>({...old,stages:old.stages.map(s=>s.id===id?{...s,[key]:v}:s)}));
  const selectTemplate=type=>{if(initial){set('type',type);return;}setValue(old=>({...old,type,title:old.title===TYPES[old.type]?.title?TYPES[type].title:old.title,stages:[makeStage(type,old.start,old.end)]}));};
  const submit=(ev,status)=>{ev.preventDefault();setError('');if(!value.title.trim()){setError('给这次见面起个名字吧');return;}onSave({...value,status:status||value.status});};
  return <form className="event-form" onSubmit={submit}>
    <div className="form-section"><div className="form-section-heading"><span>01</span><h3>这次，想做什么？</h3></div><div className="type-choices">{Object.entries(TYPES).map(([key,t])=><button type="button" key={key} className={value.type===key?'selected':''} aria-pressed={value.type===key} onClick={()=>selectTemplate(key)}><TypeIcon type={key} size={18}/>{t.name}</button>)}</div><Field label="活动名称 *"><input required maxLength={80} placeholder="给这次见面起个名字" value={value.title} onChange={e=>set('title',e.target.value)}/></Field><Field label="想对大家说"><textarea maxLength={4000} rows={3} placeholder="为什么想约这个局？有什么需要提前知道的？" value={value.description} onChange={e=>set('description',e.target.value)}/></Field></div>
    <div className="form-section"><div className="form-section-heading"><span>02</span><h3>什么时候见，几点结束？</h3></div><div className="form-grid"><Field label="开始日期 *"><input type="date" required value={value.date} onChange={e=>{const date=e.target.value;setValue(old=>({...old,date,endDate:old.endDate<date?date:old.endDate}));}}/></Field><Field label="开始时间 *"><input type="time" required value={value.start} onChange={e=>set('start',e.target.value)}/></Field><Field label="结束日期 *"><input type="date" required min={value.date} value={value.endDate} onChange={e=>set('endDate',e.target.value)}/></Field><Field label="预计结束时间 *"><input type="time" required value={value.end} onChange={e=>set('end',e.target.value)}/></Field></div><p className="field-hint">均为北京时间，整体时长包含交通、等待和休息。跨天活动请修改结束日期。</p><Field label="报名截止时间（选填）"><input type="datetime-local" value={value.deadline} onChange={e=>set('deadline',e.target.value)}/></Field></div>
    <div className="form-section"><div className="form-section-heading"><span>03</span><h3>叫上哪些伙伴？</h3><button type="button" className="text-btn" onClick={()=>set('invitees',MEMBERS.map(m=>m.id))}>全选</button></div><div className="member-choices">{MEMBERS.map(m=><button type="button" key={m.id} className={value.invitees.includes(m.id)?'selected':''} aria-pressed={value.invitees.includes(m.id)} disabled={m.id===value.creator} onClick={()=>set('invitees',value.invitees.includes(m.id)?value.invitees.filter(id=>id!==m.id):[...value.invitees,m.id])}><Avatar id={m.id} size={32}/>{m.name}{value.invitees.includes(m.id)&&<Check size={15}/>}</button>)}</div><p className="field-hint">勾选代表邀请，参加情况由每位伙伴按环节确认。</p></div>
    <div className="form-section"><div className="form-section-heading"><span>04</span><h3>把一天串起来</h3><span className="muted">{value.stages.length} 个环节</span></div><Field label="预算币种"><select value={value.currency} onChange={e=>set('currency',e.target.value)}><option value="CNY">人民币 CNY</option><option value="HKD">港币 HKD</option></select></Field>
    {value.stages.map((s,index)=><details open={index===0||undefined} className="stage-editor" key={s.id}><summary><span className="stage-editor-index">{index+1}</span><TypeIcon type={s.type} size={18}/><strong>{s.title||'新环节'}</strong><span>{s.start}–{s.end}</span><ChevronDown size={18}/></summary><div className="stage-editor-content"><div className="stage-edit-actions"><button type="button" className="text-btn" disabled={index===0} onClick={()=>{const stages=[...value.stages];[stages[index-1],stages[index]]=[stages[index],stages[index-1]];set('stages',stages);}}><ChevronUp size={15}/>上移</button><button type="button" className="text-btn" disabled={index===value.stages.length-1} onClick={()=>{const stages=[...value.stages];[stages[index],stages[index+1]]=[stages[index+1],stages[index]];set('stages',stages);}}><ChevronDown size={15}/>下移</button><button type="button" className="text-btn danger-text" disabled={value.stages.length===1} onClick={()=>set('stages',value.stages.filter(x=>x.id!==s.id))}><Trash2 size={15}/>删除环节</button></div><Field label="环节名称 *"><input required value={s.title} maxLength={80} onChange={e=>stageSet(s.id,'title',e.target.value)}/></Field><div className="form-grid"><Field label="环节开始 *"><input type="time" required value={s.start} onChange={e=>stageSet(s.id,'start',e.target.value)}/></Field><Field label="环节结束 *"><input type="time" required value={s.end} onChange={e=>stageSet(s.id,'end',e.target.value)}/></Field><Field label="地点 / 店名"><input value={s.location} placeholder={s.type==='game'?'线上语音房 / 线下场地':'地点还没确定，可以先留空'} onChange={e=>stageSet(s.id,'location',e.target.value)}/></Field><Field label="分店 / 场地区域"><input value={s.branch} placeholder="例如：白石洲店" onChange={e=>stageSet(s.id,'branch',e.target.value)}/></Field></div><Field label="具体集合点"><input value={s.meetup} placeholder="店门口、地铁几号出口，还是直接到桌边？" onChange={e=>stageSet(s.id,'meetup',e.target.value)}/></Field><Field label="详细地址"><input value={s.address} onChange={e=>stageSet(s.id,'address',e.target.value)}/></Field><div className="form-grid"><Field label="环节负责人"><select value={s.leader} onChange={e=>stageSet(s.id,'leader',e.target.value)}><option value="">待安排</option>{MEMBERS.map(m=><option key={m.id} value={m.id}>{m.name}</option>)}</select></Field><Field label="预计人均预算"><input type="number" min="0" max="100000" step="0.01" value={s.budget?s.budget/100:''} placeholder="0.00" onChange={e=>stageSet(s.id,'budget',Math.round(Number(e.target.value)*100))}/></Field></div>
      {['game','board'].includes(s.type)&&<><div className="form-grid"><Field label={s.type==='board'?'桌游名称':'游戏名称'}><input value={s.gameName} onChange={e=>stageSet(s.id,'gameName',e.target.value)}/></Field><Field label="平台 / 语音频道"><input value={s.platform} onChange={e=>stageSet(s.id,'platform',e.target.value)}/></Field></div><Field label="新手与规则说明"><input value={s.experience} placeholder="是否接受新手、谁负责教学、单局大概多久" onChange={e=>stageSet(s.id,'experience',e.target.value)}/></Field></>}
      {['shopping','outdoor'].includes(s.type)&&<><Field label="计划路线"><input value={s.route} placeholder="起点 → 途经点 → 终点" onChange={e=>stageSet(s.id,'route',e.target.value)}/></Field>{s.type==='outdoor'&&<div className="form-grid three"><Field label="距离（km）"><input type="number" min="0" step="0.1" value={s.distance} onChange={e=>stageSet(s.id,'distance',e.target.value)}/></Field><Field label="爬升（m）"><input type="number" min="0" value={s.elevation} onChange={e=>stageSet(s.id,'elevation',e.target.value)}/></Field><Field label="交通（分钟）"><input type="number" min="0" value={s.transportMinutes} onChange={e=>stageSet(s.id,'transportMinutes',e.target.value)}/></Field></div>}<Field label="休息点"><input value={s.restPoints} onChange={e=>stageSet(s.id,'restPoints',e.target.value)}/></Field><Field label="提前退出 / 返程点"><input value={s.exitPoints} onChange={e=>stageSet(s.id,'exitPoints',e.target.value)}/></Field></>}
      <details className="advanced-fields"><summary>预约、容量与更多信息<ChevronDown size={16}/></summary><Field label="地图链接（https）"><input type="url" value={s.mapUrl} placeholder="https://…" onChange={e=>stageSet(s.id,'mapUrl',e.target.value)}/></Field><Field label="人数容量（空白为不限）"><input type="number" min="0" max="100" value={s.capacity||''} onChange={e=>stageSet(s.id,'capacity',Number(e.target.value))}/></Field><Field label="预约方式"><select value={s.bookingMode} onChange={e=>stageSet(s.id,'bookingMode',e.target.value)}><option value="none">无需预约</option><option value="reservation">提前预约</option><option value="queue">现场排队</option></select></Field>{s.bookingMode==='reservation'&&<><Field label="预约结果"><select value={s.bookingStatus} onChange={e=>stageSet(s.id,'bookingStatus',e.target.value)}>{Object.entries(BOOKING).map(([k,v])=><option key={k} value={k}>{v}</option>)}</select></Field><Field label="预约编号 / 确认依据"><input value={s.bookingRef} placeholder="预约号、确认短信或桌型等" onChange={e=>stageSet(s.id,'bookingRef',e.target.value)}/></Field></>}{s.bookingMode==='queue'&&<><Field label="现场状态"><select value={s.queueStatus} onChange={e=>stageSet(s.id,'queueStatus',e.target.value)}><option value="not_taken">尚未取号</option><option value="waiting">排队中</option><option value="called">已叫号</option><option value="seated">已入场</option><option value="abandoned">已放弃</option></select></Field><div className="form-grid"><Field label="排队号码"><input value={s.queueNumber} onChange={e=>stageSet(s.id,'queueNumber',e.target.value)}/></Field><Field label="预计等待（分钟）"><input type="number" min="0" value={s.waitMinutes} onChange={e=>stageSet(s.id,'waitMinutes',e.target.value)}/></Field></div><Field label="排队信息更新时间"><input type="datetime-local" value={s.queueUpdatedAt} onChange={e=>stageSet(s.id,'queueUpdatedAt',e.target.value)}/></Field></>}<div className="form-grid"><Field label="环节开始日期（跨天时填写）"><input type="date" value={s.date||''} onChange={e=>stageSet(s.id,'date',e.target.value)}/></Field><Field label="环节结束日期（跨天时填写）"><input type="date" value={s.endDate||''} onChange={e=>stageSet(s.id,'endDate',e.target.value)}/></Field></div></details><Field label="环节说明"><textarea rows={2} value={s.notes} placeholder="交通、等待、强度、返程，以及其他需要知道的事" onChange={e=>stageSet(s.id,'notes',e.target.value)}/></Field></div></details>)}
    <div className="add-stage"><Plus size={17}/><span>追加一个环节</span><select aria-label="选择追加环节模板" value="" onChange={e=>{if(!e.target.value)return;const type=e.target.value;setValue(old=>appendStage(old,type));}}><option value="">选择场景…</option>{Object.entries(TYPES).map(([k,t])=><option key={k} value={k}>{t.name}</option>)}</select></div></div>
    <div className="form-section"><Field label="活动当前状态"><select value={value.status} onChange={e=>set('status',e.target.value)}>{Object.entries(STATUS).map(([k,v])=><option key={k} value={k}>{v}</option>)}</select></Field><p className="field-hint">征询中可以继续讨论；发布「已定案」后，请参与者确认最终安排。</p></div>{error&&<p role="alert" className="form-error"><AlertCircle size={17}/>{error}</p>}<div className="form-actions sticky-actions"><button type="button" className="btn ghost" onClick={onClose}>取消</button><button type="submit" className="btn primary" disabled={busy}>{busy?<LoaderCircle size={18} className="spin"/>:<Check size={18}/>} {initial?'保存并更新安排':value.status==='draft'?'保存草稿':'创建活动'}</button></div>
  </form>;
}

function RsvpForm({event:e,data,current,busy,onSave,onClose}){
  const [rows,setRows]=useState(()=>e.stages.map(s=>({...{stageId:s.id,status:'pending',guests:[],eta:s.start,leave:'',origin:'',transport:'',attendance:'not_started',needs:''},...data.rsvps.find(r=>r.eventId===e.id&&r.stageId===s.id&&r.memberId===current)})));
  const [ack,setAck]=useState(false);const set=(id,k,v)=>setRows(old=>old.map(r=>r.stageId===id?{...r,[k]:v}:r));
  const mustAck=['confirmed','ongoing'].includes(e.status)&&rows.some(r=>r.status==='yes');
  return <form className="rsvp-form" onSubmit={ev=>{ev.preventDefault();onSave({version:e.version,stages:rows,acknowledge:ack});}}><div className="rsvp-identity"><Avatar id={current} size={42}/><div><strong>{member(current)?.name}的报名</strong><p>{e.title} · 第 {e.version} 版</p></div></div>{e.stages.map((s,index)=>{const r=rows[index],early=r.leave&&r.leave<s.end;return <section className="rsvp-stage" key={s.id}><div className="rsvp-stage-header"><TypeIcon type={s.type} size={20}/><h3>{s.title}</h3><span>{s.start}–{s.end}</span></div><div className="rsvp-options">{[['yes','参加',Check],['maybe','待定',CircleHelp],['no','不参加',X],...(r.status==='withdrawn'?[['withdrawn','已退出',LogOut]]:[])].map(([key,label,Icon])=><button key={key} type="button" aria-pressed={r.status===key} className={r.status===key?'selected':''} onClick={()=>set(s.id,'status',key)}><Icon size={17}/>{label}</button>)}</div>{r.status==='pending'&&<p className="field-hint">还未选择，保存后仍为待回应。</p>}{['yes','maybe'].includes(r.status)&&<><div className="form-grid"><Field label="预计到达"><input type="time" value={r.eta} onChange={ev=>set(s.id,'eta',ev.target.value)}/></Field><Field label="最晚离开（选填）"><input type="time" value={r.leave} onChange={ev=>set(s.id,'leave',ev.target.value)}/></Field></div>{early&&<p className="inline-warning"><AlertCircle size={16}/>你会提前离开，请和负责人约好退出点。</p>}<details className="advanced-fields"><summary>同行者、交通与个人需求<ChevronDown size={16}/></summary><Field label="同行者昵称（逗号分隔）" hint="同行者按实际人数统计，费用份额由你代管。"><input value={r.guests.join('，')} onChange={ev=>set(s.id,'guests',ev.target.value.split(/[,，、]/))}/></Field><div className="form-grid"><Field label="从哪里出发"><input value={r.origin} onChange={ev=>set(s.id,'origin',ev.target.value)}/></Field><Field label="交通方式"><select value={r.transport} onChange={ev=>set(s.id,'transport',ev.target.value)}><option value="">待定</option>{['地铁','公交','打车','自驾','步行','过关后前往','线上参加'].map(t=><option key={t}>{t}</option>)}</select></Field></div><Field label="当前到场情况"><select value={r.attendance} onChange={ev=>set(s.id,'attendance',ev.target.value)}>{Object.entries(ATTENDANCE).map(([k,v])=><option key={k} value={k}>{v}</option>)}</select></Field><Field label="忌口、饮酒、住宿与返程需求" hint="仅本人、组织者和该环节负责人可见。"><textarea rows={2} value={r.needs} onChange={ev=>set(s.id,'needs',ev.target.value)} placeholder="例如：不吃辣、不饮酒，或需要早点返程"/></Field></details></>}</section>;})}<label className="checkbox-label"><input type="checkbox" checked={ack} required={mustAck} onChange={ev=>setAck(ev.target.checked)}/><span>我已阅读第 {e.version} 版安排{mustAck?'，确认当前时间、地点与行程。':'。'}</span></label><div className="form-actions sticky-actions"><button type="button" className="btn ghost" onClick={onClose}>取消</button><button type="submit" className="btn primary" disabled={busy}>{busy?<LoaderCircle size={18} className="spin"/>:<Check size={18}/>}保存我的报名</button></div></form>;
}

function ExpenseForm({event:e,current,data,busy,onSave,onClose}){
  const [stageId,setStage]=useState(e.stages[0].id),[title,setTitle]=useState(''),[amount,setAmount]=useState(''),[payer,setPayer]=useState(current),[ids,setIds]=useState(()=>stageCounts(e,e.stages[0].id,data.rsvps).people);
  return <form className="expense-form" onSubmit={ev=>{ev.preventDefault();onSave({stageId,title,amount:Math.round(Number(amount)*100),payer,memberIds:ids});}}><Field label="费用所属环节"><select value={stageId} onChange={ev=>{setStage(ev.target.value);setIds(stageCounts(e,ev.target.value,data.rsvps).people);}}>{e.stages.map(s=><option key={s.id} value={s.id}>{s.title}</option>)}</select></Field><Field label="费用名称 *"><input required maxLength={80} value={title} onChange={ev=>setTitle(ev.target.value)} placeholder="例如：午餐、桌游场地费"/></Field><div className="form-grid"><Field label={`总金额（${e.currency}）*`}><input type="number" required min="0.01" step="0.01" value={amount} onChange={ev=>setAmount(ev.target.value)} placeholder="0.00"/></Field><Field label="谁垫付的"><select value={payer} onChange={ev=>setPayer(ev.target.value)}>{MEMBERS.map(m=><option key={m.id} value={m.id}>{m.name}</option>)}</select></Field></div><Field label="参与分摊的人"><div className="member-choices">{MEMBERS.map(m=><button type="button" key={m.id} aria-pressed={ids.includes(m.id)} className={ids.includes(m.id)?'selected':''} onClick={()=>setIds(ids.includes(m.id)?ids.filter(id=>id!==m.id):[...ids,m.id])}><Avatar id={m.id} size={28}/>{m.name}{ids.includes(m.id)&&<Check size={14}/>}</button>)}</div></Field><p className="field-hint">已按该环节确认参加人员预选，可根据实际到场调整。同行者份额合并到主报名人。</p><div className="form-actions"><button type="button" className="btn ghost" onClick={onClose}>取消</button><button type="submit" className="btn primary" disabled={busy||!ids.length}><Check size={17}/>保存费用</button></div></form>;
}

function Schedule({data,current,go,create,selectedMember,setSelectedMember}){
  const [date,setDate]=useState('');
  const events=sortEvents(data.events.filter(e=>e.status!=='draft'&&e.status!=='cancelled'&&(selectedMember==='all'||e.invitees.includes(selectedMember))&&(!date||e.date===date)));
  const dates=[...new Set(sortEvents(data.events.filter(e=>e.status!=='draft')).map(e=>e.date))];
  return <section className="subpage"><div className="page-heading"><span className="eyebrow"><CalendarDays size={16}/>MAKE TIME FOR GOOD TIMES</span><h1>给见面，留一点时间。</h1><p>把各自忙碌的日子，凑成一起的好时光。</p></div><div className="schedule-controls"><Field label="查看谁的安排"><select value={selectedMember} onChange={ev=>setSelectedMember(ev.target.value)}><option value="all">整个小队</option>{MEMBERS.map(m=><option key={m.id} value={m.id}>{m.name}{m.id===current?'（我）':''}</option>)}</select></Field><div className="date-strip"><button className={!date?'selected':''} onClick={()=>setDate('')}>全部日期</button>{dates.map(d=><button className={date===d?'selected':''} key={d} onClick={()=>setDate(d)}><small>{new Intl.DateTimeFormat('zh-CN',{month:'short',weekday:'short'}).format(new Date(d+'T12:00:00+08:00'))}</small><strong>{d.slice(8)}</strong></button>)}</div></div><div className="schedule-list">{events.map(e=>{const rows=data.rsvps.filter(r=>r.eventId===e.id&&r.memberId===(selectedMember==='all'?current:selectedMember));const yes=rows.filter(r=>r.status==='yes');return <a className="schedule-item" href={'#event/'+e.id} key={e.id}><div className="schedule-date"><strong>{e.date.slice(8)}</strong><span>{e.date.slice(0,7).replace('-',' / ')}</span></div><span className="schedule-type" style={{background:TYPES[e.type]?.color,color:TYPES[e.type]?.ink}}><TypeIcon type={e.type} size={25}/></span><div className="schedule-info"><div><StatusPill status={e.status}/>{e.isDemo&&<small className="muted">示例</small>}</div><h3>{e.title}</h3><p><Clock3 size={14}/>{eventTime(e)}<span>·</span>{e.stages.length} 个环节{selectedMember!=='all'&&` · ${yes.length?'已确认 '+yes.length+' 段':'待本人确认'}`}</p></div><ChevronRight size={21}/></a>;})}{!events.length&&<Empty icon={CalendarDays} title="这一天，留白也很好" description="有想见的人，就发起一个新计划。"><button className="btn primary" onClick={()=>create('custom')}><Plus size={18}/>发起活动</button></Empty>}</div></section>;
}
function Team({data,current,onView}){return <section className="subpage"><div className="page-heading"><span className="eyebrow"><Users size={16}/>OUR LITTLE CREW</span><h1>六个人，一整个小世界。</h1><p>4 位男生，2 位女生。不同的日常，一样期待的见面。</p></div><div className="team-page-grid">{MEMBERS.map(m=>{const confirmed=data.events.filter(e=>data.rsvps.some(r=>r.eventId===e.id&&r.memberId===m.id&&r.status==='yes')).length;return <article className="person-card" key={m.id} style={{'--person-color':m.color,'--person-ink':m.ink}}><div className="person-decoration"><Leaf size={70}/><span>GOOD TIMES</span></div><Avatar id={m.id} size={96}/><h2>{m.name}{current===m.id&&<span className="tag">我</span>}</h2><p>每次相聚，都不能少的伙伴。</p><div className="person-stats"><span><strong>{data.events.filter(e=>e.creator===m.id).length}</strong>发起活动</span><span><strong>{confirmed}</strong>确认参加</span></div><button className="btn secondary full" onClick={()=>onView(m.id)}>查看参与活动<ArrowRight size={17}/></button></article>;})}</div></section>;}
function Profile({data,current,go,create,chooseIdentity,pendingEvents}){if(!current)return <section className="subpage"><Empty icon={UserRound} title="先认识一下，你是哪位？" description="选择小队身份，就能查看自己的报名、日程和待确认安排。"><button className="btn primary" onClick={chooseIdentity}>选择我的身份<ArrowRight size={18}/></button></Empty></section>;const mine=sortEvents(data.events.filter(e=>e.creator===current||data.rsvps.some(r=>r.eventId===e.id&&r.memberId===current)));return <section className="subpage profile-page"><div className="profile-banner"><Avatar id={current} size={80}/><div><span className="mini-eyebrow">HELLO, FRIEND</span><h1>{member(current)?.name}，下次见！</h1><p>把想做的事，和想见的人，一起放进计划。</p></div><button className="btn secondary" onClick={chooseIdentity}><UserRound size={17}/>切换身份</button></div><div className="profile-stats"><div><strong>{data.events.filter(e=>e.creator===current).length}</strong><span>我发起的</span></div><div><strong>{data.events.filter(e=>data.rsvps.some(r=>r.eventId===e.id&&r.memberId===current&&r.status==='yes')).length}</strong><span>确认参加</span></div><div><strong>{pendingEvents.length}</strong><span>新版待确认</span></div></div>{pendingEvents.length>0&&<div className="profile-pending"><h2>有新安排，等你看一眼</h2>{pendingEvents.map(e=><button key={e.id} onClick={()=>go('event/'+e.id)}><AlertCircle size={19}/>{e.title}<span>第 {e.version} 版<ChevronRight size={17}/></span></button>)}</div>}<div className="section-heading"><h2>我的活动</h2><button className="text-btn" onClick={()=>create('custom')}><Plus size={16}/>再凑一个局</button></div><div className="activity-grid profile-grid">{mine.map(e=><EventCard key={e.id} event={e} data={data} current={current} go={go}/>)}</div>{!mine.length&&<Empty title="还没有自己的计划" description="从一个小小的邀请开始吧。"><button className="btn primary" onClick={()=>create('food')}>发起活动</button></Empty>}</section>;}

createRoot(document.getElementById('root')).render(<App/>);
